@app.command(name="evaluate-clusters")
def evaluate_clusters(
    config: Path = typer.Option(..., "--config", "-c", help="Path to YAML config file"),
    elbow: bool = typer.Option(
        False, "--elbow", "-e",
        help="Run elbow analysis across a range of k values."
    ),
    k_min: int = typer.Option(50, "--k-min", help="Minimum k for elbow analysis."),
    k_max: int = typer.Option(5000, "--k-max", help="Maximum k for elbow analysis."),
    k_steps: int = typer.Option(8, "--k-steps", help="Number of k values to test in elbow analysis."),
):
    """Evaluate cluster quality metrics to help choose n_clusters.

    Computes silhouette score, Calinski-Harabasz index, and Davies-Bouldin
    index for the configured clustering. Optionally runs an elbow analysis
    across a range of k values.

    Metrics guide:
    - Silhouette: -1 to 1 (higher = better separated clusters)
    - Calinski-Harabasz: higher = denser, better separated
    - Davies-Bouldin: lower = better separated
    - Inertia: lower = tighter clusters (but always decreases with k)
    """
    import os

    from topopyscale2.config.schema import TPS2Config
    from topopyscale2.domain import Domain

    config = config.resolve()
    os.chdir(config.parent)

    console.print(f"[bold]Cluster Evaluation: {config.name}[/bold]")

    cfg = TPS2Config.from_yaml(config)
    domain = Domain(cfg)

    # Run domain setup (DEM + clustering)
    console.print("\n[bold]Step 1: Domain Setup[/bold]")
    domain.setup()

    if domain.dem_data is not None and "elevation" in domain.dem_data:
        elev = domain.dem_data["elevation"]
        console.print(f"  DEM: {elev.shape[0]}x{elev.shape[1]} pixels")
        console.print(f"  Elevation: {float(elev.min()):.0f} - {float(elev.max()):.0f} m")

    # Evaluate current clustering
    console.print(f"\n[bold]Step 2: Evaluate k={cfg.clustering.n_clusters}[/bold]")
    clustering = domain._clustering
    if clustering is None:
        console.print("[red]Error: No clustering object found. Is spatial_mode set to 'clusters'?[/red]")
        raise typer.Exit(1)

    metrics = clustering.evaluate()
    console.print(f"\n[bold]Cluster Quality Metrics (k={metrics['n_clusters']}):[/bold]")
    console.print(f"  Samples:           {metrics['n_samples']:,}")
    console.print(f"  Silhouette:        {metrics['silhouette']:.4f}  (higher is better, range -1 to 1)")
    console.print(f"  Calinski-Harabasz: {metrics['calinski_harabasz']:.1f}  (higher is better)")
    console.print(f"  Davies-Bouldin:    {metrics['davies_bouldin']:.4f}  (lower is better)")
    console.print(f"  Inertia:           {metrics['inertia']:.1f}")
    if metrics.get("silhouette_sampled"):
        console.print("  (silhouette subsampled to 50k points)")

    # Elbow analysis
    if elbow:
        console.print(f"\n[bold]Step 3: Elbow Analysis (k={k_min} to {k_max}, {k_steps} steps)[/bold]")
        k_values = [int(k) for k in np.linspace(k_min, k_max, k_steps)]
        # Include configured k if not already present
        if cfg.clustering.n_clusters not in k_values:
            k_values.append(cfg.clustering.n_clusters)
            k_values.sort()

        results = clustering.elbow_analysis(domain.dem_data, k_values)

        console.print(f"\n[bold]{'k':>6}  {'Silhouette':>10}  {'Calinski-H':>10}  {'Davies-B':>10}  {'Inertia':>14}[/bold]")
        console.print(f"  {'─'*6}  {'─'*10}  {'─'*10}  {'─'*10}  {'─'*14}")
        for m in results:
            marker = " ◄" if m["n_clusters"] == cfg.clustering.n_clusters else ""
            console.print(
                f"  {m['n_clusters']:>5}  {m['silhouette']:>10.4f}  "
                f"{m['calinski_harabasz']:>10.1f}  {m['davies_bouldin']:>10.4f}  "
                f"{m['inertia']:>14.1f}{marker}"
            )

        # Find best silhouette
        best = max(results, key=lambda m: m["silhouette"])
        console.print(f"\n  Best silhouette: k={best['n_clusters']} ({best['silhouette']:.4f})")

    console.print("\n[green]Evaluation complete.[/green]")


@app.command()
def preflight(
    config: Path = typer.Option(..., "--config", "-c", help="Path to YAML config file"),
    strict: bool = typer.Option(
        False, "--strict",
        help="Exit code 1 on any warning (for CI)."
    ),
    skip_disk: bool = typer.Option(
        False, "--skip-disk",
        help="Skip disk space check (useful for network storage)."
    ),
):
    """Run preflight checks on config before starting a simulation.

    Validates configuration parameters, checks backend availability,
    estimates runtime and data volumes, and catches obvious misconfigurations
    before committing to a multi-hour pipeline run.

    Examples:

        tps2 preflight -c config.yaml

        tps2 preflight -c config.yaml --strict

        tps2 preflight -c config.yaml --skip-disk
    """
    from topopyscale2.config.schema import TPS2Config
    from topopyscale2.preflight import run_preflight

    try:
        cfg = TPS2Config.from_yaml(config)
    except Exception as e:
        console.print(f"[red]Config parse error: {e}[/red]")
        raise typer.Exit(1)

    report = run_preflight(cfg, skip_disk=skip_disk)

    # Print with Rich markup for colored icons
    status_styles = {"pass": "green", "warn": "yellow", "fail": "red"}
    status_icons = {"pass": "\u2713", "warn": "\u26a0", "fail": "\u2717"}

    console.print(f"\n[bold]Preflight Checks: {config.name}[/bold]\n")

    # Group checks by category
    categories: dict[str, list] = {}
    for check in report.checks:
        cat = check.category or "General"
        categories.setdefault(cat, []).append(check)

    for cat, checks in categories.items():
        console.print(f"  [bold]{cat}[/bold]")
        for c in checks:
            icon = status_icons[c.status]
            style = status_styles[c.status]
            console.print(f"  [{style}]{icon}[/{style}] {c.message}")
        console.print()

    # Estimates table
    if report.estimates:
        console.print("  [bold]Estimates[/bold]")
        sep = "\u2500"
        console.print(f"  {'Stage':<20} {'Data Volume':<14} {'Est. Time'}")
        console.print(f"  {sep*20} {sep*14} {sep*14}")
        for est in report.estimates:
            console.print(f"  {est.stage:<20} {est.volume_str:<14} {est.time_str}")

        total_vol = f"~{report.total_volume_gb:.1f} GB"
        low, high = report.total_time_low, report.total_time_high
        if low < 1 and high < 1:
            total_time = f"~{high * 60:.0f}s"
        else:
            total_time = f"~{low:.0f}-{high:.0f} min"
        console.print(f"  {sep*20} {sep*14} {sep*14}")
        console.print(f"  {'Total':<20} {total_vol:<14} {total_time}")
        console.print()

    # Summary
    summary = f"  {report.n_pass} passed, {report.n_warn} warning(s), {report.n_fail} error(s)"
    if report.n_fail > 0:
        console.print(f"[red]{summary}[/red]")
    elif report.n_warn > 0:
        console.print(f"[yellow]{summary}[/yellow]")
    else:
        console.print(f"[green]{summary}[/green]")

    if report.n_fail > 0 or (strict and report.n_warn > 0):
        raise typer.Exit(1)


@app.command()
def info(
    config: Path = typer.Option(..., "--config", "-c", help="Path to YAML config file"),
):
    """Show domain summary information including Phase 2 configuration."""
    from topopyscale2.config.schema import TPS2Config

    cfg = TPS2Config.from_yaml(config)

    console.print(f"[bold]Configuration: {config}[/bold]")
    console.print("\n[bold]Domain:[/bold]")
    console.print(f"  Bbox: {cfg.domain.bbox}")
    console.print(f"  DEM source: {cfg.domain.dem_source}")
    console.print(f"  Spatial mode: {cfg.domain.spatial_mode}")
    console.print(f"  CRS: {cfg.domain.crs}")

    if cfg.domain.spatial_mode == "polygons":
        console.print("\n[bold]Polygon Configuration:[/bold]")
        console.print(f"  Method: {cfg.polygons.method}")
        console.print(f"  Elevation bands: {cfg.polygons.elevation_bands}m")
        console.print(f"  Aspect classes: {cfg.polygons.aspect_classes}")
        console.print(f"  Respect catchments: {cfg.polygons.respect_catchments}")
        console.print(f"  Min area: {cfg.polygons.min_area_m2} m2")
    else:
        console.print("\n[bold]Clustering:[/bold]")
        console.print(f"  Method: {cfg.clustering.method}")
        console.print(f"  N clusters: {cfg.clustering.n_clusters}")
        console.print(f"  Features: {cfg.clustering.features}")

    console.print("\n[bold]Inputs:[/bold]")
    console.print(f"  Primary: {cfg.inputs.primary}")
    console.print(f"  Backend: {cfg.inputs.backend}")
    console.print(f"  Time range: {cfg.inputs.time_range}")

    if cfg.inputs.sources:
        console.print(f"  NWP sources: {len(cfg.inputs.sources)}")
        for src in cfg.inputs.sources:
            console.print(f"    - {src.name} ({src.type}, priority {src.priority})")
        console.print(f"  Blending: {cfg.inputs.blending.method if cfg.inputs.blending.enabled else 'disabled'}")

    console.print("\n[bold]Downscaling:[/bold]")
    # What the engine does with this config (not the informational method strings).
    d = cfg.downscaling
    if d.mode == "full":
        levels = ", ".join(str(p) for p in cfg.inputs.pressure_levels)
        console.print(f"  Temperature, humidity: pressure levels ({levels} hPa) at each unit's elevation")
    else:
        console.print(f"  Temperature: surface + fixed lapse rate {d.lapse_rate * 1000:.2f} °C/km")
    console.print("  Radiation: slope, aspect, horizon shading and sky-view correction")
    console.print(f"  Wind: {d.wind_config.method}")
    if d.precipitation == "elevation_gradient":
        console.print(f"  Precipitation: ERA5 amount scaled by {d.precip_gradient * 1e4:.1f} % per 100 m")
    else:
        console.print("  Precipitation: ERA5 amount for every unit (no elevation gradient)")
    console.print(f"  Rain/snow: {d.phase_method}, all snow below {d.t_snow_threshold_c} °C, "
                  f"all rain above {d.t_rain_threshold_c} °C (and above {d.t_air_max_c} °C air)")

    if cfg.downscaling.redistribution.wind_transport or cfg.downscaling.redistribution.avalanche:
        console.print("\n[bold]Redistribution:[/bold]")
        console.print(f"  Wind transport: {cfg.downscaling.redistribution.wind_transport}")
        console.print(f"  Avalanche: {cfg.downscaling.redistribution.avalanche}")
        if cfg.downscaling.redistribution.avalanche:
            console.print(f"  Avalanche threshold: {cfg.downscaling.redistribution.avalanche_slope_threshold} deg")

    console.print("\n[bold]Execution:[/bold]")
    console.print(f"  Backend: {cfg.execution.backend}")
    console.print(f"  Kernel backend: {cfg.execution.kernel_backend}")
    console.print(f"  Workers: {cfg.execution.n_workers}")

    if cfg.execution.backend == "slurm":
        console.print(f"  SLURM partition: {cfg.execution.slurm.partition}")
        console.print(f"  SLURM time: {cfg.execution.slurm.time}")

    console.print("\n[bold]Output:[/bold]")
    console.print(f"  Format: {cfg.output.format}")
    console.print(f"  Directory: {cfg.output.directory}")
    console.print(f"  Variables: {len(cfg.output.variables)} configured")

    console.print("\n[bold]Storage:[/bold]")
    console.print(f"  Cache format: {cfg.storage.input_cache_format}")
    console.print(f"  Working format: {cfg.storage.working_format}")
    console.print(f"  Compression: {cfg.storage.compression}")

    if cfg.application.model != "none":
        console.print("\n[bold]Application:[/bold]")
        console.print(f"  Model: {cfg.application.model}")
        console.print(f"  Feedback: {cfg.application.feedback.method if cfg.application.feedback.enabled else 'disabled'}")
        console.print(f"  State DA: {cfg.application.state_da.method if cfg.application.state_da.enabled else 'disabled'}")


