@app.command()
def view(
    sim_dir: Path = typer.Argument(..., help="Simulation directory (after `tps2 run`)"),
    output: Optional[Path] = typer.Option(
        None, "--output", "-o", help="HTML file to write (default: <sim_dir>/output/forcing_page.html)"),
    page: Optional[Path] = typer.Option(
        None, "--page", help="YAML with the page's title, text, credits and logo"),
    save_daily: bool = typer.Option(
        False, "--save-daily",
        help="Also write output/forcing_daily.nc, a compact daily summary the page can be rebuilt from"),
):
    """Write a self-contained HTML page of the downscaled forcing.

    One offline file: pick temperature, precipitation, snowfall, shortwave, longwave, wind or
    humidity and watch it through the season on the terrain, against elevation, and at any
    terrain unit.

    Examples:
        tps2 view ~/sim/alps_2023
        tps2 view ~/sim/alps_2023 -o alps.html --page page.yaml
    """
    from topopyscale2.outputs.forcing_page import (
        PageText,
        generate_forcing_page,
        write_daily_summary,
    )

    if save_daily:
        path = write_daily_summary(sim_dir)
        console.print(f"[green]Daily summary:[/green] {path}")
    spec = PageText.from_yaml(page) if page else None
    out = generate_forcing_page(sim_dir, output, page=spec)
    console.print(f"[green]Forcing page:[/green] {out}")


@app.command()
def ui(
    sim_dir: Path = typer.Argument(Path("."), help="Simulation directory to configure and run (created if missing)"),
    port: int = typer.Option(8765, "--port", "-p", help="Port on 127.0.0.1"),
    no_browser: bool = typer.Option(False, "--no-browser", help="Do not open a browser tab"),
):
    """Open a local page to configure a run, start it and view the result.

    Serves on 127.0.0.1 only (it has no login). Stop it with Ctrl+C.

    Examples:
        tps2 ui ~/sim/davos
        tps2 ui ~/sim/davos --port 8800 --no-browser
    """
    import webbrowser

    from topopyscale2.ui.server import make_server

    sim_dir = sim_dir.resolve()
    sim_dir.mkdir(parents=True, exist_ok=True)
    server, _state = make_server(sim_dir, port=port)
    url = f"http://127.0.0.1:{server.server_address[1]}/"
    console.print(f"[green]tps2 ui[/green] for {sim_dir}\n  {url}   (Ctrl+C to stop)")
    if not no_browser:
        webbrowser.open(url)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        console.print("stopped")
    finally:
        server.server_close()


@app.command(name="build-cache")
def build_cache(
    output: Path = typer.Argument(..., help="Path to output Zarr store (e.g. ./era5_cache/region.zarr)"),
    bbox: Optional[str] = typer.Option(
        None, "--bbox", "-b",
        help="Bounding box: west,south,east,north (e.g. 60,25,105,50)",
    ),
    time: Optional[str] = typer.Option(
        None, "--time", "-t",
        help="Time range: start,end (e.g. 2000-01-01,2024-12-31)",
    ),
    levels: str = typer.Option(
        "1000,925,850,800,700,600,550,500,400,300",
        "--levels", "-l",
        help="Comma-separated pressure levels in hPa",
    ),
    backend: str = typer.Option(
        "google", "--backend",
        help="Download backend (google, cds, openmeteo)",
    ),
    workers: int = typer.Option(
        4, "--workers", "-w",
        help="Number of parallel download workers",
    ),
    resolution: str = typer.Option(
        "1H", "--resolution", "-r",
        help="Time resolution (1H, 2H, 3H, 6H)",
    ),
    update: bool = typer.Option(
        False, "--update", "-u",
        help="Update existing cache with new dates",
    ),
    info: bool = typer.Option(
        False, "--info",
        help="Print cache metadata and exit",
    ),
    chunk_lat: int = typer.Option(45, "--chunk-lat", help="Latitude chunk size"),
    chunk_lon: int = typer.Option(45, "--chunk-lon", help="Longitude chunk size"),
    no_throttle: bool = typer.Option(
        False, "--no-throttle",
        help="Disable adaptive rate limiting (not recommended for large builds)",
    ),
    yes: bool = typer.Option(False, "--yes", "-y", help="Skip confirmation prompt"),
):
    """Build a regional ERA5 Zarr cache for fast local access.

    Downloads ERA5 data and consolidates into a single Zarr store with
    optimised regional chunking. Subsequent simulations using backend=local
    read from this cache in seconds instead of re-downloading.

    Examples:

        tps2 build-cache ./era5_cache/region.zarr --bbox 60,25,105,50 --time 2000-01-01,2024-12-31

        tps2 build-cache ./era5_cache/region.zarr --info

        tps2 build-cache ./era5_cache/region.zarr --update
    """
    from rich.table import Table

    from topopyscale2.inputs.nwp_downloader.cache_builder import CacheBuilder

    output = output.resolve()

    # ── Info mode ──────────────────────────────────────────────────────
    if info:
        if not output.exists():
            console.print(f"[red]Cache not found: {output}[/red]")
            raise typer.Exit(1)

        meta = CacheBuilder.info(output)

        table = Table(title=f"Cache: {output}")
        table.add_column("Property", style="bold")
        table.add_column("Value")

        table.add_row("Version", str(meta["cache_version"]))
        table.add_row("Bbox", str(meta["bbox"]))
        table.add_row("Time range", f"{meta['time_range'][0]} to {meta['time_range'][1]}")
        table.add_row("Days", f"{meta['n_days']} / {meta['expected_days']} expected")
        table.add_row("Missing days", str(len(meta["missing_days"])))
        table.add_row("Pressure levels", str(meta["pressure_levels"]))
        table.add_row("Surface vars", ", ".join(meta["surf_vars"]))
        table.add_row("Plev vars", ", ".join(meta["plev_vars"]))
        table.add_row("Time resolution", meta["time_resolution"])
        table.add_row("Chunks", str(meta["chunks"]))
        table.add_row("Size", f"{meta['size_gb']:.2f} GB")

        if meta["missing_days"]:
            n = len(meta["missing_days"])
            sample = meta["missing_days"][:5]
            gaps = ", ".join(sample)
            if n > 5:
                gaps += f" ... (+{n - 5} more)"
            table.add_row("Gap dates", gaps)

        console.print(table)
        raise typer.Exit()

    # ── Update mode ───────────────────────────────────────────────────
    if update:
        if not output.exists():
            console.print(f"[red]Cache not found: {output}[/red]")
            raise typer.Exit(1)

        console.print(f"[bold]Updating cache: {output}[/bold]")
        CacheBuilder.update(
            output,
            backend=backend,
            max_workers=workers,
        )
        console.print("[green]Cache updated.[/green]")
        raise typer.Exit()

    # ── Build mode ────────────────────────────────────────────────────
    if not bbox:
        console.print("[red]--bbox is required for initial build (e.g. --bbox 60,25,105,50)[/red]")
        raise typer.Exit(1)
    if not time:
        console.print("[red]--time is required for initial build (e.g. --time 2000-01-01,2024-12-31)[/red]")
        raise typer.Exit(1)

    # Parse bbox
    try:
        bbox_parts = [float(x.strip()) for x in bbox.split(",")]
        if len(bbox_parts) != 4:
            raise ValueError
        bbox_tuple = tuple(bbox_parts)
    except (ValueError, AttributeError):
        console.print("[red]Invalid bbox format. Use: west,south,east,north[/red]")
        raise typer.Exit(1)

    # Parse time range
    try:
        time_parts = [x.strip() for x in time.split(",")]
        if len(time_parts) != 2:
            raise ValueError
        start_date, end_date = time_parts
    except (ValueError, AttributeError):
        console.print("[red]Invalid time format. Use: start,end (e.g. 2000-01-01,2024-12-31)[/red]")
        raise typer.Exit(1)

    # Parse pressure levels
    pressure_levels = [int(x.strip()) for x in levels.split(",")]

    # Estimate size
    import pandas as pd

    n_days = (pd.Timestamp(end_date) - pd.Timestamp(start_date)).days + 1
    w, s, e, n = bbox_tuple
    n_lat = int(abs(n - s) / 0.25) + 1
    n_lon = int(abs(e - w) / 0.25) + 1
    n_levels = len(pressure_levels)
    hours_per_day = {"1H": 24, "2H": 12, "3H": 8, "6H": 4}.get(resolution, 24)

    # Rough estimate: 15 vars * 4 bytes * time * lat * lon * compression ~0.3x
    bytes_est = 15 * 4 * n_days * hours_per_day * n_lat * n_lon * 0.3
    # Add plev contribution
    bytes_est += 5 * 4 * n_days * hours_per_day * n_lat * n_lon * n_levels * 0.3
    gb_est = bytes_est / (1024**3)

    console.print("[bold]Build ERA5 cache[/bold]")
    console.print(f"  Output:     {output}")
    console.print(f"  Bbox:       {bbox_tuple}")
    console.print(f"  Time:       {start_date} to {end_date} ({n_days} days)")
    console.print(f"  Levels:     {pressure_levels}")
    console.print(f"  Grid:       {n_lat} x {n_lon} (~{n_lat * n_lon} points)")
    console.print(f"  Resolution: {resolution}")
    console.print(f"  Backend:    {backend}")
    console.print(f"  Est. size:  ~{gb_est:.0f} GB")

    if not yes:
        confirm = typer.confirm("Proceed?")
        if not confirm:
            raise typer.Exit()

    chunks = {
        "time": 24,
        "latitude": chunk_lat,
        "longitude": chunk_lon,
        "level": -1,
    }

    backend_kwargs = {}
    if no_throttle:
        backend_kwargs["throttle"] = False

    builder = CacheBuilder(
        backend=backend,
        bbox=bbox_tuple,
        start_date=start_date,
        end_date=end_date,
        pressure_levels=pressure_levels,
        output_path=output,
        chunks=chunks,
        max_workers=workers,
        time_resolution=resolution,
        backend_kwargs=backend_kwargs,
    )
    builder.build()

    console.print(f"[green]Cache built: {output}[/green]")

    # Print summary
    meta = CacheBuilder.info(output)
    console.print(f"  Size: {meta['size_gb']:.2f} GB, {meta['n_days']} days")


