# Commands outside the v1 downscaling core. Each module registers its commands on
# `app` when imported; a release that does not ship a module simply lacks them. Only
# an ABSENT module is skipped: a module that is present but fails to import raises,
# so a broken optional command can never vanish silently.
def _register_optional_commands() -> None:
    import importlib
    import importlib.util

    for name in ("stations_cli", "forecast_cli", "snow_cli", "da_cli"):
        if importlib.util.find_spec(f"topopyscale2.cli.{name}") is not None:
            importlib.import_module(f"topopyscale2.cli.{name}")
    for name, attr, group in (("climate_cli", "climate_app", "climate"),
                              ("topoclim_cli", "topoclim_app", "topoclim"),
                              ("lab_cli", "lab_app", "lab")):
        if importlib.util.find_spec(f"topopyscale2.cli.{name}") is not None:
            app.add_typer(getattr(importlib.import_module(f"topopyscale2.cli.{name}"), attr), name=group)


_register_optional_commands()


# Last, after the optional commands are registered: `python -m topopyscale2.cli.main`
# (how the operational run.sh scripts call TPS2) runs this module as __main__, and would
# otherwise start the app with only the core commands.
if __name__ == "__main__":
    app()
